final class AccountManagementExperience
{
    private const ROUTES=['/admin/accounts','/admin/accounts/view'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user||!AccessPolicy::canManageAccounts($user))self::forbidden();$_SESSION['accounts_csrf']??=bin2hex(random_bytes(24));
        if($_SERVER['REQUEST_METHOD']==='POST')self::handlePost($db,$user,$basePath,$route);
        $account=null;if($route==='/admin/accounts/view'){$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$account=self::account($db,(int)$id);}self::page($db,$user,$basePath,$route,$account);
    }

    private static function handlePost(PDO $db,array $actor,string $basePath,string $route):never
    {
        if(!hash_equals((string)($_SESSION['accounts_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired.');self::redirect($basePath.'/admin/accounts');}
        $id=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT)?:0;$action=(string)($_POST['action']??'');
        try{
            if($id<1)throw new RuntimeException('Choose a valid account.');
            if($action==='invite'){
                $account=self::account($db,$id);if(!$account||empty($account['email']))throw new RuntimeException('That account needs an email address before invitation.');$token=Auth::createInvitation($db,$id,(int)$actor['id']);$link=self::absoluteUrl($basePath.'/activate?token='.$token);$_SESSION['accounts_invite_link']=$link;$text="Hi {$account['name']},\n\nYou have been invited to CTSMD Connect. Activate your account and choose a password using this private link:\n{$link}\n\nThis link expires in 7 days.\n\n— Children’s Theatre of Southern Maryland";MailService::queue($db,$id,(string)$account['email'],(string)$account['name'],'account_security','Your CTSMD Connect invitation',$text,null,'account-invite-'.$id.'-'.hash('sha256',$token));self::audit($db,(int)$actor['id'],'account.invited',$id,'Issued account invitation.');self::flash('success','Invitation created and queued for email delivery.');
            }elseif($action==='save_contact') {self::saveContact($db,$actor,$id,$_POST);self::flash('success','Account contact details updated.');
            }elseif($action==='save_roles'){self::saveRoles($db,$actor,$id,(array)($_POST['role_ids']??[]));self::flash('success','Account roles updated.');
            }elseif($action==='toggle_status'){self::toggleStatus($db,$actor,$id);self::flash('success','Account availability updated.');
            }elseif($action==='membership_status'){self::setMembershipStatus($db,$actor,$id,(string)($_POST['membership_status']??''));self::flash('success','CTSMD membership approval updated.');
            }elseif(in_array($action,['add_relationship','deactivate_relationship'],true)){
                throw new RuntimeException('Family relationships are now managed through each child’s Family & Pickup page, including staff review and pickup authorization.');
            }elseif($action==='verify_credential'){if(!AccessPolicy::canManageVolunteers($actor))throw new RuntimeException('Volunteer management permission is required.');$requirementId=filter_input(INPUT_POST,'requirement_id',FILTER_VALIDATE_INT)?:0;self::verifyCredential($db,$actor,$id,(int)$requirementId,(string)($_POST['completed_at']??''),(string)($_POST['expires_at']??''),trim((string)($_POST['note']??''))?:null);self::flash('success','Volunteer requirement verified. Shift eligibility updates immediately.');
            }else throw new RuntimeException('Choose a valid account action.');
        }catch(RuntimeException $e){self::flash('error',$e->getMessage());}
        self::redirect($basePath.'/admin/accounts/view?id='.$id);
    }

    private static function saveContact(PDO $db,array $actor,int $id,array $input):void
    {
        $first=trim((string)($input['first_name']??''));$last=trim((string)($input['last_name']??''));
        if($first===''||$last===''||mb_strlen($first)>100||mb_strlen($last)>100)throw new RuntimeException('Enter a valid first and last name.');
        $dob=PersonEligibility::birthDate((string)($input['date_of_birth']??''),false);
        $contact=PersonEligibility::contact($input,false);
        $db->beginTransaction();
        try{
            $previous=$db->prepare('SELECT id,date_of_birth FROM users WHERE id=:id AND active=1 FOR UPDATE');$previous->execute(['id'=>$id]);$before=$previous->fetch(PDO::FETCH_ASSOC);
            if(!$before)throw new RuntimeException('Account unavailable.');
            $stmt=$db->prepare("UPDATE users SET first_name=:first,last_name=:last,initials=:initials,date_of_birth=:dob,contact_phone=:phone,address_line1=:line1,address_line2=:line2,address_city=:city,address_state=:state,address_postal_code=:postal WHERE id=:id AND active=1");
            $stmt->execute(['first'=>$first,'last'=>$last,'initials'=>mb_strtoupper(mb_substr($first,0,1).mb_substr($last,0,1)),'dob'=>$dob,'phone'=>$contact['contact_phone'],'line1'=>$contact['address_line1'],'line2'=>$contact['address_line2'],'city'=>$contact['address_city'],'state'=>$contact['address_state'],'postal'=>$contact['address_postal_code'],'id'=>$id]);
            self::audit($db,(int)$actor['id'],'account.contact_updated',$id,'Updated account demographic and contact information.',['dob_changed'=>(string)($before['date_of_birth']??'')!==(string)($dob??'')]);
            $db->commit();
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('Contact details could not be saved.');}
    }

    private static function setMembershipStatus(PDO $db,array $actor,int $userId,string $status):void
    {
        if(!in_array($status,['pending','approved','denied'],true))throw new RuntimeException('Choose a valid CTSMD membership status.');
        $stmt=$db->prepare('SELECT organization_membership_status,email,CONCAT(first_name,\' \',last_name) name FROM users WHERE id=:id AND active=1 LIMIT 1');$stmt->execute(['id'=>$userId]);$before=$stmt->fetch();if(!$before)throw new RuntimeException('That account no longer exists.');
        $db->prepare('UPDATE users SET organization_membership_status=:status,organization_membership_reviewed_at=CURRENT_TIMESTAMP,organization_membership_reviewed_by_user_id=:actor WHERE id=:id')->execute(['status'=>$status,'actor'=>(int)$actor['id'],'id'=>$userId]);
        self::audit($db,(int)$actor['id'],'membership.'.$status,$userId,'Updated CTSMD organization membership approval.',['before'=>$before['organization_membership_status'],'after'=>$status]);
        if($status==='approved'&&!empty($before['email'])){try{$body="Hi {$before['name']},\n\nYour CTSMD Connect membership has been approved. You can now access CTSMD’s general member Community and organization-wide member resources. Production-specific access will appear when CTSMD adds you or your household to an active production.\n\n— Children’s Theatre of Southern Maryland";MailService::queue($db,$userId,(string)$before['email'],(string)$before['name'],'account_security','Your CTSMD Connect membership is approved',$body,null,'membership-approved-'.$userId.'-'.time());}catch(Throwable){}}
    }

    private static function saveRoles(PDO $db,array $actor,int $userId,array $roleIds):void
    {
        $ids=array_values(array_unique(array_filter(array_map('intval',$roleIds),static fn(int $id):bool=>$id>0)));$roles=self::roles($db);$allowed=array_column($roles,'id');foreach($ids as $id)if(!in_array($id,$allowed,true))throw new RuntimeException('One or more roles are invalid.');$adminRoleId=0;foreach($roles as $role)if($role['code']==='administrator')$adminRoleId=(int)$role['id'];if($userId===(int)$actor['id']&&!in_array($adminRoleId,$ids,true))throw new RuntimeException('You cannot remove your own Administrator role.');IdentityRolePolicy::assertRoleSelection($db,$userId,$ids);$db->beginTransaction();try{$before=Auth::roles($db,$userId);$db->prepare('DELETE FROM auth_user_roles WHERE user_id=:user')->execute(['user'=>$userId]);$insert=$db->prepare('INSERT INTO auth_user_roles (user_id,role_id,assigned_by_user_id) VALUES (:user,:role,:actor)');foreach($ids as $roleId)$insert->execute(['user'=>$userId,'role'=>$roleId,'actor'=>(int)$actor['id']]);self::audit($db,(int)$actor['id'],'account.roles_updated',$userId,'Updated account roles.',['before'=>$before,'after'=>Auth::roles($db,$userId)]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('Roles could not be updated.');}
    }

    private static function toggleStatus(PDO $db,array $actor,int $userId):void
    {
        if($userId===(int)$actor['id'])throw new RuntimeException('You cannot disable your own account.');$s=$db->prepare('SELECT account_status,password_hash FROM users WHERE id=:id LIMIT 1');$s->execute(['id'=>$userId]);$row=$s->fetch();if(!$row)throw new RuntimeException('That account no longer exists.');if($row['account_status']==='disabled'){$managed=$db->prepare("SELECT 1 FROM family_relationships fr JOIN auth_user_roles ur ON ur.user_id=fr.student_user_id JOIN auth_roles r ON r.id=ur.role_id AND r.code='student' WHERE fr.student_user_id=:user AND fr.status='active' LIMIT 1");$managed->execute(['user'=>$userId]);$next=$managed->fetchColumn()?'managed':(empty($row['password_hash'])?'invited':'active');}else{$next='disabled';}$db->prepare('UPDATE users SET account_status=:status WHERE id=:id')->execute(['status'=>$next,'id'=>$userId]);self::audit($db,(int)$actor['id'],$next==='disabled'?'account.disabled':'account.enabled',$userId,'Changed account availability.',['status'=>$next]);
    }

    private static function addRelationship(PDO $db,int $actorId,int $guardianId,int $studentId,string $type):void
    {
        if(!in_array($type,['parent','guardian','caregiver'],true))throw new RuntimeException('Choose a valid relationship type.');IdentityRolePolicy::assertFamilyPair($db,$guardianId,$studentId);
        $db->beginTransaction();try{$sql="INSERT INTO family_relationships (guardian_user_id,student_user_id,relationship_type,is_primary,status,created_by_user_id) VALUES (:guardian,:student,:relationship_type,0,'active',:actor) ON DUPLICATE KEY UPDATE relationship_type=VALUES(relationship_type),status='active',created_by_user_id=VALUES(created_by_user_id),updated_at=CURRENT_TIMESTAMP";$db->prepare($sql)->execute(['guardian'=>$guardianId,'student'=>$studentId,'relationship_type'=>$type,'actor'=>$actorId]);$idStmt=$db->prepare('SELECT id FROM family_relationships WHERE guardian_user_id=:guardian AND student_user_id=:student LIMIT 1');$idStmt->execute(['guardian'=>$guardianId,'student'=>$studentId]);$relationshipId=(int)$idStmt->fetchColumn();self::auditSubject($db,$actorId,'family.relationship_saved','family_relationship',$relationshipId,'Saved family relationship.',['guardian_user_id'=>$guardianId,'student_user_id'=>$studentId,'relationship_type'=>$type,'status'=>'active']);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The family relationship could not be saved.');}
    }

    private static function deactivateRelationship(PDO $db,int $actorId,int $relationshipId):void
    {
        if($relationshipId<1)throw new RuntimeException('That relationship could not be found.');$db->beginTransaction();try{$stmt=$db->prepare("SELECT id,guardian_user_id,student_user_id,relationship_type,status FROM family_relationships WHERE id=:id FOR UPDATE");$stmt->execute(['id'=>$relationshipId]);$relationship=$stmt->fetch();if(!$relationship||$relationship['status']!=='active')throw new RuntimeException('That relationship is already inactive or unavailable.');$count=$db->prepare("SELECT COUNT(DISTINCT fr.guardian_user_id) FROM family_relationships fr JOIN users guardian ON guardian.id=fr.guardian_user_id AND guardian.active=1 AND guardian.account_status<>'disabled' WHERE fr.student_user_id=:student AND fr.status='active'");$count->execute(['student'=>(int)$relationship['student_user_id']]);if((int)$count->fetchColumn()<=1)throw new RuntimeException('A live Student must retain at least one available parent, guardian, or caregiver. Add another guardian before deactivating this relationship.');$update=$db->prepare("UPDATE family_relationships SET status='inactive',updated_at=CURRENT_TIMESTAMP WHERE id=:id AND status='active'");$update->execute(['id'=>$relationshipId]);if($update->rowCount()<1)throw new RuntimeException('That relationship is already inactive or unavailable.');self::auditSubject($db,$actorId,'family.relationship_deactivated','family_relationship',$relationshipId,'Deactivated family relationship.',['guardian_user_id'=>(int)$relationship['guardian_user_id'],'student_user_id'=>(int)$relationship['student_user_id'],'relationship_type'=>$relationship['relationship_type'],'status'=>'inactive']);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The family relationship could not be deactivated.');}
    }

    private static function verifyCredential(PDO $db,array $actor,int $userId,int $requirementId,string $completed,string $expires,?string $note):void
    {
