    }

    private static function accounts(PDO $db):array{return $db->query("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name,u.email,u.initials,u.display_role,u.account_status,u.organization_membership_status,u.last_login_at,GROUP_CONCAT(r.name ORDER BY r.name SEPARATOR ', ') role_names FROM users u LEFT JOIN auth_user_roles ur ON ur.user_id=u.id LEFT JOIN auth_roles r ON r.id=ur.role_id WHERE u.active=1 GROUP BY u.id,u.first_name,u.last_name,u.email,u.initials,u.display_role,u.account_status,u.organization_membership_status,u.last_login_at ORDER BY FIELD(u.organization_membership_status,'pending','denied','approved'),u.last_name,u.first_name")->fetchAll();}
    private static function account(PDO $db,int $id):?array{if($id<1)return null;$s=$db->prepare("SELECT id,CONCAT(first_name,' ',last_name) name,email,initials,display_role,account_status,organization_membership_status,organization_membership_reviewed_at,last_login_at,password_changed_at,first_name,last_name,date_of_birth,contact_phone,address_line1,address_line2,address_city,address_state,address_postal_code FROM users WHERE id=:id AND active=1 LIMIT 1");$s->execute(['id'=>$id]);$a=$s->fetch();if(!$a)return null;$a['roles']=Auth::roles($db,$id);return $a;}
    private static function roles(PDO $db):array{return $db->query("SELECT id,code,name,description FROM auth_roles WHERE active=1 ORDER BY FIELD(code,'administrator','production_staff','moderator','safeguarding','volunteer','member','student'),name")->fetchAll();}
    private static function relationshipCandidates(PDO $db,int $excludeId):array{$s=$db->prepare("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name,u.display_role role,EXISTS(SELECT 1 FROM auth_user_roles ur JOIN auth_roles r ON r.id=ur.role_id AND r.active=1 AND r.code='student' WHERE ur.user_id=u.id) is_student FROM users u WHERE u.active=1 AND u.account_status<>'disabled' AND u.id<>:exclude ORDER BY u.last_name,u.first_name");$s->execute(['exclude'=>$excludeId]);return$s->fetchAll();}
    private static function relationships(PDO $db,int $userId,bool $isStudent):array{if($isStudent){$s=$db->prepare("SELECT fr.id relationship_id,fr.relationship_type,fr.is_primary,u.id,CONCAT(u.first_name,' ',u.last_name) name,u.display_role role FROM family_relationships fr JOIN users u ON u.id=fr.guardian_user_id WHERE fr.student_user_id=:user AND fr.status='active' AND u.active=1 AND u.account_status<>'disabled' ORDER BY fr.is_primary DESC,u.last_name,u.first_name");}else{$s=$db->prepare("SELECT fr.id relationship_id,fr.relationship_type,fr.is_primary,u.id,CONCAT(u.first_name,' ',u.last_name) name,u.display_role role FROM family_relationships fr JOIN users u ON u.id=fr.student_user_id WHERE fr.guardian_user_id=:user AND fr.status='active' AND u.active=1 AND u.account_status<>'disabled' ORDER BY fr.is_primary DESC,u.last_name,u.first_name");}$s->execute(['user'=>$userId]);return$s->fetchAll();}
    private static function volunteerProfile(PDO $db,int $userId):bool{$s=$db->prepare('SELECT 1 FROM volunteer_profiles WHERE user_id=:user AND active=1 LIMIT 1');$s->execute(['user'=>$userId]);return(bool)$s->fetchColumn();}
    private static function requirements(PDO $db):array{return$db->query('SELECT id,name,category,expires FROM volunteer_requirements ORDER BY category,name')->fetchAll();}
    private static function credentials(PDO $db,int $userId):array{$s=$db->prepare("SELECT vc.id,vc.status,vc.completed_at,vc.expires_at,vr.name,vr.category,vr.expires,CONCAT(verifier.first_name,' ',verifier.last_name) verifier_name FROM volunteer_credentials vc JOIN volunteer_requirements vr ON vr.id=vc.requirement_id LEFT JOIN users verifier ON verifier.id=vc.verified_by_user_id WHERE vc.user_id=:user ORDER BY vr.category,vr.name");$s->execute(['user'=>$userId]);return$s->fetchAll();}

    private static function page(PDO $db,array $user,string $basePath,string $route,?array $account):never
    {
        $url=static fn(string $p):string=>($basePath?:'').$p;$e=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');$flash=$_SESSION['accounts_flash']??null;$invite=$_SESSION['accounts_invite_link']??null;unset($_SESSION['accounts_flash'],$_SESSION['accounts_invite_link']);$roles=self::roles($db);$accounts=self::accounts($db);$canPeople=AccessPolicy::canManagePeople($user);$canVolunteer=AccessPolicy::canManageVolunteers($user);header('Content-Type:text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Account & Access · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/account-access.css?v=20261021-spacing')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Administration',$account?$account['name']:'Account & Access',$basePath,[['label'=>'Accounts','href'=>'/admin/accounts','active'=>$route==='/admin/accounts'&&($_GET['view']??'')!=='denied'],['label'=>'Denied memberships','href'=>'/admin/accounts?view=denied','active'=>$route==='/admin/accounts'&&($_GET['view']??'')==='denied']]);?><div class="acct-page"><?php if($flash):?><div class="acct-flash <?=$e($flash['type'])?>"><?=$e($flash['message'])?></div><?php endif;?><?php if($invite):?><section class="acct-invite"><small>ACTIVATION LINK · ALSO QUEUED FOR EMAIL</small><code><?=$e($invite)?></code></section><?php endif;?>
        <?php if($route==='/admin/accounts'):
        $deniedView=($_GET['view']??'')==='denied';
        $activeAccounts=[];$disabledAccounts=[];$deniedAccounts=[];
        foreach($accounts as $a){
            if($a['organization_membership_status']==='denied')$deniedAccounts[]=$a;
            elseif($a['account_status']==='disabled')$disabledAccounts[]=$a;
            else $activeAccounts[]=$a;
        }
        $listRows=static function(array $rows)use($url,$e):void{foreach($rows as $a):$search=mb_strtolower(implode(' ',[(string)$a['name'],(string)$a['email'],(string)$a['role_names'],(string)$a['organization_membership_status'],(string)$a['account_status']]));?>
