        <?php endforeach;};
        $listHeader=static function():void{?><div class="acct-list-columns op-table-columns"><span>Account</span><span>Roles</span><span>Membership</span><span>Sign-in</span><span>Last login</span><span>Action</span></div><?php };
        ?>
        <section class="acct-hero"><div><small>PEOPLE + FAMILY + ACCESS</small><h2><?=$deniedView?'Denied memberships':'Account & Access'?></h2><p><?=$deniedView?'Membership applications previously denied. Review an account to make an authorized status change.':'Find active and pending accounts, manage access, and review disabled accounts separately.'?></p></div></section>
        <?php if($deniedView):?><a class="acct-back" href="<?=$url('/admin/accounts')?>">← Back to accounts</a><?php else:?><div class="acct-view-links"><span><?=count($activeAccounts)?> accounts · <?=count($disabledAccounts)?> disabled</span><a href="<?=$url('/admin/accounts?view=denied')?>">Denied memberships (<?=count($deniedAccounts)?>) →</a></div><?php endif;?>
