        <script>(()=>{const input=document.getElementById('acct-search-input');const list=document.getElementById('acct-active-list');if(!input||!list)return;const rows=[...list.querySelectorAll('[data-account-row]')],empty=list.querySelector('[data-account-empty]'),count=document.querySelector('[data-account-search-count]');const filter=()=>{const q=input.value.trim().toLocaleLowerCase(),visible=rows.filter(row=>{const yes=(row.dataset.search||'').includes(q);row.hidden=!yes;return yes;}).length;if(empty)empty.hidden=visible!==0;if(count)count.textContent=visible+' of '+rows.length+' shown';};input.addEventListener('input',filter);filter();})();</script>
