        <section class="acct-panel" style="margin:0 0 18px"><div class="acct-panel-heading"><small>PERSONAL &amp; CONTACT INFORMATION</small><h3>Account details</h3><p>Used for communications and age-restricted auditions or signups. A Student's birth date belongs to the Student, not their guardian.</p></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><div class="acct-form-row"><label>First name<input name="first_name" maxlength="100" value="<?=$e((string)$account['first_name'])?>" required></label><label>Last name<input name="last_name" maxlength="100" value="<?=$e((string)$account['last_name'])?>" required></label></div><div class="acct-form-row"><label>Date of birth<input type="date" name="date_of_birth" max="<?=date('Y-m-d')?>" value="<?=$e((string)($account['date_of_birth']??''))?>"></label><label>Phone<input type="tel" name="contact_phone" autocomplete="tel" maxlength="40" value="<?=$e((string)($account['contact_phone']??''))?>"></label></div><label>Street address<input name="address_line1" autocomplete="address-line1" maxlength="190" value="<?=$e((string)($account['address_line1']??''))?>"></label><label>Address line 2<input name="address_line2" autocomplete="address-line2" maxlength="190" value="<?=$e((string)($account['address_line2']??''))?>"></label><div class="acct-form-row"><label>City<input name="address_city" autocomplete="address-level2" maxlength="100" value="<?=$e((string)($account['address_city']??''))?>"></label><label>State<input name="address_state" autocomplete="address-level1" maxlength="60" value="<?=$e((string)($account['address_state']??''))?>"></label><label>ZIP / postal code<input name="address_postal_code" autocomplete="postal-code" maxlength="20" value="<?=$e((string)($account['address_postal_code']??''))?>"></label></div><button name="action" value="save_contact" type="submit">Save contact details</button></form></section><div class="acct-layout"><section class="acct-panel acct-access-panel"><div class="acct-panel-heading"><small>MEMBERSHIP & AUTHORIZATION</small><h3>Access</h3><p>Membership controls general CTSMD access. Roles grant administrative authority.</p></div><div class="acct-block"><h4>CTSMD membership</h4><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><label>Membership status<select name="membership_status"><?php foreach(['pending','approved','denied'] as $status):?><option value="<?=$status?>"<?=$account['organization_membership_status']===$status?' selected':''?>><?=ucfirst($status)?></option><?php endforeach;?></select></label><button name="action" value="membership_status" type="submit">Update membership</button></form></div><div class="acct-divider"></div><div class="acct-block"><h4>Authorization roles</h4><div class="acct-role-list"><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><?php foreach($roles as $role):?><label class="acct-role"><input type="checkbox" name="role_ids[]" value="<?=(int)$role['id']?>"<?=in_array($role['code'],$account['roles'],true)?' checked':''?>><span><b><?=$e($role['name'])?></b><small><?=$e((string)$role['description'])?></small></span></label><?php endforeach;?><button name="action" value="save_roles" type="submit">Save roles</button></form></div></div></section>
        <aside class="acct-rail"><section class="acct-panel acct-lifecycle"><div class="acct-panel-heading"><small>ACCOUNT</small><h3>Lifecycle</h3></div><dl><div><dt>Sign-in</dt><dd><?=$e(ucwords(str_replace('_',' ',$account['account_status'])))?></dd></div><div><dt>CTSMD membership</dt><dd><?=$e(ucfirst($account['organization_membership_status']))?></dd></div><div><dt>Last login</dt><dd><?=$account['last_login_at']?$e(date('M j, Y · g:i A',strtotime($account['last_login_at']))):'Never'?></dd></div></dl><?php if($account['email']&&$account['account_status']!=='managed'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><button name="action" value="invite" type="submit">Issue new invitation</button></form><?php endif;?><?php if($accountId!==(int)$user['id']):?><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><button class="danger" name="action" value="toggle_status" type="submit"><?=$account['account_status']==='disabled'?'Enable account':'Disable account'?></button></form><?php endif;?></section>
        <?php if($canPeople):?><section class="acct-panel acct-family-card"><div class="acct-panel-heading"><small>FAMILY & SAFEGUARDING</small><h3><?=$isStudent?'Guardian relationships':'Family relationships'?></h3><p><?=$isStudent?'Adults linked to this student provide guardian context for safeguarded communication.':'Students linked here inherit this adult’s guardian context.'?></p></div><div class="acct-family-list"><?php if($isStudent):?><p style="margin:0 0 14px"><a class="button secondary" href="<?=$url('/student-profile/family?student='.$accountId)?>">Manage family &amp; authorized pickup →</a></p><?php else:?><p class="acct-muted">Select a linked student below to manage that child's family relationships and authorized pickup people.</p><?php endif;?><h4><?=$isStudent?'Guardians & caregivers':'Linked students'?></h4><?php if($links):?><div class="acct-records"><?php foreach($links as $link):?><article class="acct-record compact"><span><b><?=$e((string)$link['name'])?></b><small><?=$e(ucfirst((string)$link['relationship_type']))?><?=$link['is_primary']?' · Primary':''?></small><?php if(!$isStudent):?><a href="<?=$url('/student-profile/family?student='.(int)$link['id'])?>" style="display:inline-block;margin-top:5px;color:#a6192e;font-size:12px;font-weight:800">Manage family &amp; pickup →</a><?php endif;?></span><?php if($isStudent):?><a class="button secondary" href="<?=$url('/student-profile/family?student='.$accountId)?>">Manage</a><?php endif;?></article><?php endforeach;?></div><?php else:?><div class="acct-empty-state"><b>No active links</b><span>No family relationships are recorded for this person.</span></div><?php endif;?></div><div class="acct-add-family"><p class="acct-muted">Add or change a relationship from the child's Family &amp; Pickup page, where pickup authorization and staff review are managed together.</p><?php if($isStudent):?><a class="button secondary" href="<?=$url('/student-profile/family?student='.$accountId)?>">Open Family &amp; Pickup →</a><?php endif;?></div></section><?php endif;?></aside></div>
        <?php if($canVolunteer):?><section class="acct-panel acct-readiness"><header class="acct-section-head"><div><small>VOLUNTEER ELIGIBILITY</small><h3>Readiness & training</h3></div><p>Verified requirements determine whether this person can register for restricted volunteer shifts.</p></header><?php if(!$isVolunteer):?><div class="acct-empty-state readiness"><b>No active volunteer profile</b><span>Eligibility credentials can be recorded once this person has an active volunteer profile.</span><a href="<?=$url('/admin/volunteer-development')?>">Open volunteer development →</a></div><?php else:?><div class="acct-readiness-grid"><div class="acct-credential-column"><div class="acct-subhead"><div><h4>Current credentials</h4><p><?=count($credentials)?> recorded requirement<?=count($credentials)===1?'':'s'?></p></div></div><?php if($credentials):?><div class="acct-records credential-list"><?php foreach($credentials as $credential):$expired=!empty($credential['expires_at'])&&strtotime((string)$credential['expires_at'])<time();?><article class="acct-record credential"><span><b><?=$e((string)$credential['name'])?></b><small><?=$e((string)$credential['category'])?><?php if($credential['completed_at']):?> · verified <?=date('M j, Y',strtotime((string)$credential['completed_at']))?><?php endif;?><?php if($credential['expires_at']):?> · expires <?=date('M j, Y',strtotime((string)$credential['expires_at']))?><?php endif;?></small></span><em class="<?=$expired?'expired':'current'?>"><?=$expired?'Renew':'Current'?></em></article><?php endforeach;?></div><?php else:?><div class="acct-empty-state"><b>No verified requirements</b><span>Use the verification form to add the first credential.</span></div><?php endif;?></div><div class="acct-verify-card"><div class="acct-subhead"><div><h4>Verify requirement</h4><p>Record a background check, facility education, certification, or training completion.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=$e((string)$_SESSION['accounts_csrf'])?>"><input type="hidden" name="user_id" value="<?=$accountId?>"><label>Requirement<select name="requirement_id" required><option value="">Choose requirement</option><?php foreach($requirements as $r):?><option value="<?=(int)$r['id']?>"><?=$e((string)$r['name'])?> · <?=$e((string)$r['category'])?><?=$r['expires']?' · expires':''?></option><?php endforeach;?></select></label><div class="acct-form-row"><label>Verified date<input type="date" name="completed_at" value="<?=$e($today)?>" required></label><label>Expiration <span>if required</span><input type="date" name="expires_at"></label></div><label>Internal note<input name="note" maxlength="1000" placeholder="Confirmation or record reference"></label><button name="action" value="verify_credential" type="submit">Verify requirement</button></form><a class="acct-inline-link" href="<?=$url('/admin/volunteer-development')?>">Manage requirements & training →</a></div></div><?php endif;?></section><?php endif;?>
        <?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function audit(PDO $db,int $actor,string $event,int $subject,string $summary,array $meta=[]):void{self::auditSubject($db,$actor,$event,'user',$subject,$summary,$meta);}
    private static function auditSubject(PDO $db,int $actor,string $event,string $subjectType,int $subject,string $summary,array $meta=[]):void{$s=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:subject_type,:subject,:summary,:meta)');$s->execute(['actor'=>$actor,'event'=>$event,'subject_type'=>$subjectType,'subject'=>$subject,'summary'=>$summary,'meta'=>$meta?json_encode($meta,JSON_THROW_ON_ERROR):null]);}
    private static function absoluteUrl(string $path):string{$configured=rtrim((string)(getenv('APP_URL')?:''),'/');if($configured!==''){ $base=(string)(getenv('APP_BASE_PATH')?:'');if($base!==''&&str_ends_with(strtolower($configured),strtolower($base)))return $configured.substr($path,strlen($base));return $configured.$path;}$scheme=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http';$host=(string)($_SERVER['HTTP_HOST']??'localhost');return $scheme.'://'.$host.$path;}
    private static function flash(string $type,string $message):void{$_SESSION['accounts_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
    private static function forbidden():never{http_response_code(403);exit('Restricted');}
}
